namespace ghidra.app.plugin.compare;

using static ghidra.util.datastruct.Duo.Side;
using static org.junit.Assert;




using org.junit;

using ghidra.features.@base.codecompare.model;
using ghidra.features.codecompare.decompile;
using ghidra.features.codecompare.decompile;
using ghidra.features.codecompare.plugin;
using ghidra.features.codecompare.plugin;
using ghidra.program.model.address;
using ghidra.program.model.listing;
using ghidra.test;
using ghidra.util.datastruct.Duo;

/**
 * Tests for the {@link FunctionComparisonPlugin function comparison plugin}
 * that involve the GUI
 */
public class CompareFunctionsDecompilerViewTest : AbstractGhidraHeadedIntegrationTest {

	private TestEnv env;
	private Program program1;
	private Function fun1;
	private Function fun2;
	private FunctionComparisonPlugin plugin;

	/* @Before */
	public void setUp()
    {
		env = new TestEnv();
		program1 = buildTestProgram();
		env.showTool(program1);
		plugin = env.addPlugin(typeof(FunctionComparisonPlugin));

		FunctionManager functionManager = program1.getFunctionManager();
		fun1 = functionManager.getFunctionAt(addr(0x01002cf5));
		fun2 = functionManager.getFunctionAt(addr(0x0100415a));
	}

	private Address addr(long offset) {
		return program1.getAddressFactory().getDefaultAddressSpace().getAddress(offset);
	}

	/* @After */
	public void tearDown()
    {
		env.dispose();
	}

	/* @Test */
	public void testDecompilerDiffView()
    {
		assertFalse(program1.isClosed());

		Set<Function> functions = Set.of(fun1, fun2);
		compareFunctions(functions);

		FunctionComparisonProvider provider =
			waitForComponentProvider(typeof(FunctionComparisonProvider));

		checkFunctions(provider, LEFT, fun1, fun1, fun2);
		DecompilerCodeComparisonView comparisonProvider =
			(DecompilerCodeComparisonView) provider
					.getView(DecompilerCodeComparisonView.NAME);

		waitForDecompiler(provider, comparisonProvider);
		assertHasLines(comparisonProvider.getLeftPanel(), 28);
		assertHasLines(comparisonProvider.getRightPanel(), 22);
	}

	private void checkFunctions(FunctionComparisonProvider provider, Side side,
			Function activeFunction, params Function[] functions) {
		Set<Function> funcs = Set.of(functions);

		FunctionComparisonModel model = provider.getModel();
		assertEquals(activeFunction, model.getActiveFunction(side));

		List<Function> fcs = model.getFunctions(side);
		assertEquals(fcs.size(), funcs.size());
		assertTrue(fcs.containsAll(funcs));
	}

	private void assertHasLines(CDisplay panel, int lineCount) {
		assertEquals(lineCount, panel.getDecompilerPanel().getLines().size());
	}

	private void waitForDecompiler(FunctionComparisonProvider provider,
			DecompilerCodeComparisonView view) {

		runSwing(() => provider.setActiveView(view.getName()));
		waitForSwing();

		waitForCondition(() => !view.isBusy());
		waitForSwing();
	}

	private void compareFunctions(Set<Function> functions) {
		runSwing(() => plugin.createComparison(functions));
		waitForSwing();
	}

	private Program buildTestProgram()
    {
		ClassicSampleX86ProgramBuilder builder = new ClassicSampleX86ProgramBuilder("Test", false);
		return builder.getProgram();
	}

}
